+export const markEventsConsumed = async (eventIds: string[]): Promise<void> => {
+  if (eventIds.length === 0) return;
+  const placeholders = eventIds.map((_, i) => `$${i + 1}`).join(",");
+  await pool.query(`UPDATE job_events SET consumed = true WHERE id IN (${placeholders})`, eventIds);
