@@ -0,0 +1,46 @@
+import { getUnconsumedEvents, markEventsConsumed, JobEvent } from "./jobs.ts";
+
+const PORT = 3000;
+
+const server = Deno.serve({ port: PORT }, async (req: Request) => {
+  const url = new URL(req.url);
+
+  if (url.pathname === "/api/events" && req.method === "GET") {
+    return handleGetEvents();
+  }
+
+  if (url.pathname === "/api/events/acknowledge" && req.method === "POST") {
+    return handleAcknowledgeEvents(req);
+  }
+
+  return new Response("Not found", { status: 404 });
+});
+
+async function handleGetEvents(): Promise<Response> {
+  try {
+    const events = await getUnconsumedEvents();
+    return Response.json(events);
+  } catch (error) {
+    console.error("Error fetching events:", error);
+    return new Response("Internal server error", { status: 500 });
+  }
+}
+
+async function handleAcknowledgeEvents(req: Request): Promise<Response> {
+  try {
+    const body = await req.json();
+    const { event_ids } = body as { event_ids: string[] };
+
+    if (!Array.isArray(event_ids)) {
+      return new Response("Invalid request: event_ids must be an array", { status: 400 });
+    }
+
+    await markEventsConsumed(event_ids);
+    return Response.json({ acknowledged: event_ids.length });
+  } catch (error) {
+    console.error("Error acknowledging events:", error);
+    return new Response("Internal server error", { status: 500 });
+  }
+}
+
+console.log(`Server running on http://localhost:${PORT}`);
